import {icon,WORKER_ICONS,RESOURCE_ICONS} from './icons.mjs';
import {mobileShell,suggestedScreen,frameMap} from './mobile-ui.mjs';
import {originalCatalog,playerDashboard} from './original-ui.mjs';
import {interactionDialog} from './interaction-ui.mjs';
import {movementOptions} from './map-rules.mjs';
import {LAND_NODES,nearestLand} from './map-data.mjs';
import {automaticPanel,autoDialog as legacyAutoDialog} from './automation-ui.mjs';
import {tollSites,quoteTolls,HAZARD_POSITIONS} from './tolls.mjs';
import {sarahPanel} from './sarah-ui.mjs';
import {createGame,reduce,current,score,sheepValue,validateSave,VERSION} from './engine.mjs';
import {COLORS,WORKERS,WORKER_NAMES,PHASES,NEUTRAL,SCORE_LABELS,SCORE_TIPS,cardInfo,HELP} from './data.mjs';
const root=document.querySelector('#app'),modal=document.querySelector('#modal');
const KEY='table-nz-base-v1';
const mobileQuery=matchMedia('(max-width:900px)');
let mobileScreen='turn',mobileState=null,mobileMapView=null;
const isMobile=()=>mobileQuery.matches;
let catalog,state=null,history=[],selected=new Set(),tab='turn',zoom=100,mapChoice=null,movePreview=null,previewState=null,placing=null,curtain=false,saveError='',toastTimer;
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(id,label,disabled=false,cls='')=>`<button data-action="${id}" ${disabled?'disabled':''} class="${cls}">${label}</button>`;
const info=c=>cardInfo(catalog.cards[c.def]);
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4800);}
function save(){try{localStorage.setItem(KEY,JSON.stringify({state,history:history.slice(-15)}));saveError='';}catch{saveError='浏览器存储不可用，请导出存档以免丢失进度。';toast(saveError);}}
function dispatch(a){try{const old=state;state=reduce(state,a,catalog);history.push(old);if(history.length>30)history.shift();selected.clear();save();render();return true;}catch(error){toast(error.message);return false;}}
function batch(actions){try{const old=state;let next=state;for(const a of actions)next=reduce(next,a,catalog);state=next;history.push(old);if(history.length>30)history.shift();selected.clear();save();render();return true;}catch(e){toast(e.message);return false;}}
function top(){return `<header class="top"><a class="brand" href="../../">← 桌边</a><span class="title">大西部开拓者：新西兰</span><span class="preview-badge">${state&&!state.rulesVersion?'旧版辅助桌面':'自动规则'}</span><div class="tools">${state?button('undo','↶ 撤销',!history.length)+button('export','导出存档')+button('scores','计分')+button('new','新对局'):button('import','导入存档')}</div></header>`;}
function card(c,attr='',caption=true){const d=info(c);return `<button class="card ${selected.has(c.uid)?'selected':''}" ${attr} title="${escape(d.name)}" aria-label="${escape(d.name)}" ${attr.includes('data-hand')?`aria-pressed="${selected.has(c.uid)}"`:''}><img src="${d.image}" alt="${escape(d.name)}" loading="lazy">${caption?`<span class="caption">${escape(d.name)}</span>`:''}</button>`;}
function tile(t,attr='',caption=''){const d=catalog.tiles[t.def];return `<button class="card" ${attr} title="${escape(caption||d.name)}"><img src="${t.side==='b'?d.back:d.image}" alt="${escape(caption||d.name)}" loading="lazy"><span class="caption">${escape(caption||d.name)}</span></button>`;}
function showDialog(content,setup){modal.innerHTML=`<div class="dialog-body"><button class="close" aria-label="关闭" id="close-modal">×</button>${content}</div>`;modal.querySelector('#close-modal').onclick=()=>modal.close();if(!modal.open)modal.showModal();setup?.();}
function formDialog(title,body,fields,run,submit='确认'){showDialog(`<h2>${escape(title)}</h2>${body}<form id="dialog-form">${fields}<p class="error" id="form-error" role="alert"></p><div class="dialog-actions"><button type="submit" class="primary">${submit}</button><button type="button" id="cancel-form">取消</button></div></form>`,()=>{modal.querySelector('#cancel-form').onclick=()=>modal.close();modal.querySelector('form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);try{const result=run(data);if(result!==false)modal.close();}catch(err){modal.querySelector('#form-error').textContent=err.message;}};});}
function number(name,label,value,min=0,max=999){return `<div class="form-row"><label>${label}<input name="${name}" type="number" step="1" min="${min}" max="${max}" value="${value}" required></label></div>`;}
function showLanding(){root.innerHTML=top()+`<main class="landing"><section class="hero-nz"><div class="intro"><span class="eyebrow">GREAT WESTERN TRAIL · NEW ZEALAND</span><h1>赶着羊群，<br>走向下一座港口。</h1><p>沿新西兰南岛经营牧场，购买绵羊、雇用工人，<br>把羊毛与希望运往更远的海岸。</p><form id="setup-form"><div class="setup-fields"><label>游玩方式<select name="players"><option value="sarah">单人 · 官方莎拉</option><option value="1">单人基础练习（无对手）</option><option value="2">2 人同屏</option><option value="3">3 人同屏</option><option value="4">4 人同屏</option></select></label><label>莎拉难度<select name="difficulty"><option value="easy">简单</option><option value="medium">中等</option><option value="hard">困难</option></select></label><label>建筑面<select name="buildingFaces"><option value="a">全部 a 面（首次游戏）</option><option value="b">全部 b 面</option><option value="mixed">随机混合（所有玩家相同）</option></select></label><label>奖励卡组<select name="bonus"><option value="1,2,3,4">组 1 / 2 / 3 / 4</option><option value="5,6,7,8">组 5 / 6 / 7 / 8</option><option value="7,8,9,10">组 7 / 8 / 9 / 10</option><option value="random">随机四组</option></select></label></div><button class="primary full" type="submit">展开桌面 →</button></form><p class="bottom-note">自动存档 · 独立矢量界面 · 中文规则随时查阅</p></div><div class="hero-map" style="background-image:url('${catalog.board}')"></div></section><div class="notice">新对局使用自动规则：按地点提供可执行行动，自动计算费用、奖励、路线与资源变化。莎拉单人模式按官方行动规则运行；自动筛选路线、建造落位及港口，规则允许的并列方案由你选择。</div>${saveError?`<p class="error">${escape(saveError)}</p>`:''}<div class="features"><article><h3>一张完整的地图</h3><p>清晰的建筑、海路、市场和贸易站。放大地图，点选配件，记录牧场主的旅途。</p></article><article><h3>把牌库交给桌面</h3><p>真实卡牌数量，抽牌堆耗尽时自动洗入弃牌。运羊与剃毛按不同品种计算。</p></article><article><h3>一步步完成回合</h3><p>阶段提示、可撤销操作和十二项计分表。适合熟悉规则，也可用于同屏对局。</p></article></div></main>`;root.querySelector('#setup-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);let groups=String(data.get('bonus')).split(',').map(Number);if(data.get('bonus')==='random'){groups=Array.from({length:10},(_,i)=>i+1);for(let i=9;i>0;i--){const j=Math.floor(Math.random()*(i+1));[groups[i],groups[j]]=[groups[j],groups[i]];}groups=groups.slice(0,4);}state=createGame(catalog,{players:data.get('players')==='sarah'?2:Number(data.get('players')),mode:data.get('players')==='sarah'?'sarah':'base',difficulty:data.get('difficulty'),bonusGroups:groups,automation:true,buildingFaces:data.get('buildingFaces')});history=[];selected.clear();save();render();};}
function autoDialog(s,c,key,helpers){if(!interactionDialog(s,c,key,{showDialog,formDialog,modal,dispatch,pickMap}))legacyAutoDialog(s,c,key,helpers);}
function pickMap(title,targets,choose,hint){mapChoice={state,title,targets,choose,hint};modal.close();tab='turn';mobileScreen='map';render();const el=root.querySelector('[data-map-choice]');el?.scrollIntoView({block:'center',inline:'center'});el?.focus({preventScroll:true});if(!targets.length)toast('当前没有可选择的合法位置');}
function mapChoiceOverlay(){return mapChoice?mapChoice.targets.map((t,i)=>`<button class="map-choice ${t.port?'port-choice':''}" style="left:${t.x}%;top:${t.y}%" data-map-choice="${i}" aria-label="${escape(t.label)}" title="${escape(t.label)}">${t.marker?escape(t.marker):t.port?'⌂':t.id.startsWith('sea:')?'⚓':i+1}</button>`).join(''):'';}
function canMapMove(){return state?.rulesVersion&&state.phase==='A'&&!current(state).isSarah&&!state.pending&&!state.ruleTasks?.length;}
function mapRoutes(){return canMapMove()?movementOptions(state,catalog):[];}
function previewRoute(){if(previewState!==state){movePreview=null;previewState=state;}return mapRoutes().find(r=>r.path.join('|')===movePreview);}
function chooseDestination(id){const routes=mapRoutes().filter(r=>r.destination===id);if(!routes.length){toast('此地点不在本回合可达范围内，请点击高亮地点');return;}movePreview=routes[0].path.join('|');previewState=state;tab='turn';render();}
function focusMap(){if(isMobile()&&mobileScreen!=='map'){mobileScreen='map';render();}const el=root.querySelector('[data-move-destination]');el?.scrollIntoView({block:'center',inline:'center'});el?.focus({preventScroll:true});}
function movementPanel(){const r=previewRoute();return `<h2>在地图上选择目的地</h2><p>点击高亮地点预览路线，确认后自动扣除过路费。</p>${r?`<h3>${escape(LAND_NODES[r.destination].label)}</h3><div class="move-routes">${mapRoutes().filter(t=>t.destination===r.destination).map((t,i)=>`<button data-move-path="${escape(t.path.join('|'))}" aria-pressed="${t.path.join('|')===movePreview}">路线 ${i+1} · ${t.steps} 步 · ${t.fee} 元<br><small>${escape(t.path.map(id=>LAND_NODES[id].label).join(' → '))}</small></button>`).join('')}</div><p role="status">本次移动 ${r.steps} 步，自动支付 ${r.fee} 元。地图连线表示经过地点的顺序。</p><button data-move-confirm class="primary full">确认移动</button><button data-move-cancel class="full">取消选择</button>`:'<button data-auto="move" class="primary full">定位可达地点</button>'}`;}
function movementOverlay(){const r=previewRoute(),routes=mapRoutes(),ids=[...new Set(routes.map(t=>t.destination))];const path=r?[...(current(state).hasMoved?[current(state).landNode||'start']:[]),...r.path]:[];return `${path.length>1?`<svg class="move-lines" viewBox="0 0 2000 3000" aria-hidden="true"><polyline points="${path.map(id=>`${LAND_NODES[id].x*20},${LAND_NODES[id].y*30}`).join(' ')}"/></svg>`:''}${ids.map(id=>{const n=LAND_NODES[id];return `<button class="move-target ${r?.destination===id?'chosen':''}" style="left:${n.x}%;top:${n.y}%" data-move-destination="${id}" aria-label="移动至${escape(n.label)}" aria-pressed="${r?.destination===id}"><span>${escape(id)}</span></button>`;}).join('')}`;}
function rancherPosition(player){return state.rulesVersion&&LAND_NODES[player.landNode]?LAND_NODES[player.landNode]:player.position;}
function boardHtml(){const p=current(state);const tilePieces=NEUTRAL.map(n=>({def:n.id,uid:n.id,x:n.x,y:n.y,neutral:true,side:state.neutralFlipped&&['B','C','G','H'].includes(n.letter)?'b':'a'}));
 const workers=state.workers.map(t=>({...t,x:81.6+WORKERS.indexOf(catalog.tiles[t.def].name)*4.6,y:57.2+t.row*3.35,small:true,market:'worker'}));
 const bonuses=state.bonuses.map(t=>({...t,x:81.6+(4-state.count+t.col)*4.6,y:76.2+t.row*3.3,small:true,market:'bonus'}));
 const hazards=state.hazards.map(t=>{const flood=catalog.tiles[t.def].name==='flood',positions=HAZARD_POSITIONS[flood?'flood':'rockfall'];return {...t,x:positions[t.slot][0],y:positions[t.slot][1],small:true,market:'hazard'};});
 const pieces=[...tilePieces,...workers,...bonuses,...hazards,...state.boardPieces.filter(t=>t.type==='building')];
 return `<div class="board-toolbar"><span>南岛与海路 · 移动时点击高亮地点，其余阶段点击建筑查看</span><div class="controls">${button('zoomout','−',zoom<=70)}<span>${zoom}%</span>${button('zoomin','+',zoom>=250)}${button('fit',isMobile()?'全景':'适应宽度')}${button('land','南岛')}${button('sea','海路')}${button('mapHelp',isMobile()?'?':'操作说明')}</div></div>${placing?`<div class="placing-banner"><span>${escape(placing.text)}，然后点击地图</span>${button('cancelPlacement','取消')}</div>`:''}<div class="board-viewport ${placing?'placing':''}" id="board-viewport"><div class="board" id="board" style="width:${zoom}%"><img class="map" src="${catalog.board}" alt="新西兰完整地图：上部海路，下部南岛路线，右侧市场" draggable="false">${pieces.map(t=>{const d=catalog.tiles[t.def];return `<button class="piece tile ${t.small?'small-tile':''}" style="left:${t.x}%;top:${t.y}%" data-piece="${t.uid}" data-market="${t.market||''}" ${t.neutral?`data-neutral="${t.uid}"`:''} aria-label="${escape(t.neutral?'中立建筑 '+NEUTRAL.find(n=>n.id===t.uid).letter:d.name)}"><img src="${t.side==='b'?d.mapBack:d.mapImage}" alt="${escape(d.name)}"></button>`;}).join('')}${state.boardPieces.filter(t=>t.type!=='building').map(t=>`<button class="piece token ${t.type}" style="left:${t.x}%;top:${t.y}%;--owner:${COLORS[t.owner]}" data-token="${t.uid}" aria-label="${escape(state.players[t.owner].name+' '+(t.label||t.type))}">${t.type==='warehouse'?'⌂':'●'}</button>`).join('')}${state.players.map((player,i)=>`<button class="piece token rancher" style="left:${rancherPosition(player).x+(i-state.active)*1.4}%;top:${rancherPosition(player).y}%;--owner:${COLORS[i]}" data-rancher="${i}" title="${escape(player.name)}" aria-label="${escape(player.name)}牧场主">♟</button><button class="piece token ship" style="left:${player.ship.x}%;top:${player.ship.y+i*1.2}%;--owner:${COLORS[i]}" data-ship="${i}" aria-label="${escape(player.name)}帆船">⚓</button>`).join('')}${movementOverlay()}${mapChoiceOverlay()}<button class="wellington" data-action="wellington">抵达威灵顿 ↗</button></div></div><p class="bottom-note">新对局按地图连接计算移动与建造位置。全部操作记录在日志，可撤销。</p>`;
}
function handHtml(){const p=current(state);if(p.isSarah)return `<section class="hand-panel"><h3>莎拉的牧场</h3><p>莎拉不使用手牌，也不抽绵羊牌。获得的卡牌保留到终局计分。</p><div class="actions-row">${p.workers.map((n,i)=>`<span class="chip">${WORKER_NAMES[i]} ${n}</span>`).join('')}<span class="chip">绵羊／建构卡 ${p.discard.length}</span><span class="chip">目标卡 ${p.objectives.length}</span></div></section>`;let values='选择手牌以弃牌、剃毛或运羊';if(selected.size){try{values=`已选 ${selected.size} 张 · 育种 ${sheepValue(state,catalog,[...selected])} · 羊毛 ${sheepValue(state,catalog,[...selected],'wool')}`;}catch{values=`已选 ${selected.size} 张（含同品种或非绵羊牌）`;}}
 return `<section class="hand-panel"><div class="hand-head"><strong>你的手牌 <small>${p.hand.length} / ${p.handLimit}</small></strong><span>${escape(values)}</span></div>${state.pending?`<div class="notice">抽换牌尚未完成：请选择 ${state.pending.discard} 张手牌，点击「弃掉所选」。完成之前不能进行其他操作。</div>`:''}<div class="cards">${p.hand.map(c=>card(c,`data-hand="${c.uid}"`,false)).join('')||'<p class="muted">手牌为空；结束回合时补牌。</p>'}</div><div class="hand-actions">${button('discard','弃掉所选',!selected.size||(state.rulesVersion&&!state.pending&&state.phase!=='start'))}${button('cardDetail','查看／打出',selected.size!==1)}${button('exchange',`交换（${p.exchange}）`,!p.exchange||!!state.pending)}${state.rulesVersion?'':button('draw','效果抽牌',!!state.pending)}${button('showDiscard',`弃牌堆 ${p.discard.length}`)}<span class="stack-count">牌库 ${p.deck.length}</span></div></section>`;
}
const RESOURCE_LABELS={money:'钱币',gold:'金块',exchange:'交换',pioneer:'开拓者',certificate:'临时认证',wool:'永久羊毛',handLimit:'手牌上限',steps:'移动上限',certificateMax:'认证上限',permanentCertificate:'永久认证',disks:'剩余圆片',warehouses:'剩余仓库'};
function resources(){const p=current(state);return `<div class="resources">${['money','gold','exchange','pioneer','certificate','wool'].map(k=>`<button class="resource" data-resource="${k}">${icon(RESOURCE_ICONS[k])}<b>${p[k]}</b>${RESOURCE_LABELS[k]}</button>`).join('')}</div>`;}
function phaseRibbon(){const active=state.phase==='A'?0:state.phase==='C'?2:1;return `<div class="phase-ribbon" aria-label="回合步骤">${[['map','移动'],['action','地点行动'],['hand','补牌']].map(([glyph,label],i)=>`<span class="${i===active?'current':i<active?'complete':''}">${icon(glyph)}<b>${i+1}</b>${label}</span>`).join('')}</div>`;}
function turnPanel(){return (state.phase==='sarah'?'':phaseRibbon())+turnPanelContent();}
function turnPanelContent(){if(mapChoice)return resources()+`<h2>${escape(mapChoice.title)}</h2><p>${escape(mapChoice.hint||'点击地图上的高亮位置，查看费用并确认。')}${mapChoice.targets.length?'':'当前没有合法位置。'}</p><button data-map-cancel class="full">取消地图选择</button>`;if(canMapMove())return resources()+movementPanel();if(state.rulesVersion&&state.phase!=='sarah'){const panel=automaticPanel(state,catalog);if(panel)return resources()+panel;}if(state.phase==='sarah')return sarahPanel(state,catalog,{escape,button});const p=current(state),n=NEUTRAL.find(n=>`中立建筑 ${n.letter}`===p.location);
 let content='';
 if(state.phase==='start')content=`<h2>准备第一次出发</h2><p>起始钱币、牌库与市场已准备好。首次行动前，将手牌弃到 4 张，再移除一个白色边框圆片放到开拓者轨 0 格。</p>${button('start','放置开拓者圆片 →',p.hand.length!==4,'primary full')}<p class="bottom-note">解锁的圆片能力请在「牧场」记录。首次出发可直接选择任一中立建筑。</p>`;
 if(state.phase==='A')content=`<h2>沿着道路，继续前行</h2><p>本回合移动上限 <b>${p.steps}</b> 步。点击地图上的中立建筑，或选择手动定位，在地图上放置牧场主。</p>${button('manualMove','选择地图位置',false,'primary full')}<p class="bottom-note">只有已放置板块的地点计步；选择经过的收费地点后，自动计算过路费并支付给各接收方。</p>`;
 if(state.phase==='B')content=`<h2>${escape(p.location||'地点行动')}</h2><p>按原图执行行动，用下方工具结算。每项完成后打勾；尚未自动核验行动资格。</p>${n?(state.neutralFlipped&&['B','C','G','H'].includes(n.letter)?['按当前 II 面执行行动（点击建筑查看卡面）']:n.actions).map((a,i)=>`<div class="task ${p.used.includes(String(i))?'done':''}"><span>${i+1}. ${a}</span><button class="check" data-mark="${i}" ${p.used.includes(String(i))?'disabled':''}>${p.used.includes(String(i))?'✓':'记完成'}</button></div>`).join(''):''}<div class="actions-row">${button('shear','给所选绵羊剃毛')}${button('marketTab','雇工／购羊')}${button('aux','附属行动')}${button('placeShip','移动帆船')}${button('placeDisk','放置圆片')}${button('placeWarehouse','放置仓库')}</div>${button('finishB','地点行动结束 →',!!state.pending,'primary full')}`;
 if(state.phase==='income')content=`<h2>威灵顿 · 领取收入</h2><p>选择要运送的绵羊，每种品种最多一张。其余手牌保留；临时认证由你决定使用多少。</p>${button('income','计算所选绵羊收入 →',false,'primary full')}`;
 if(state.phase==='delivery')content=`<h2>威灵顿 · 运送</h2><p>本次育种价值 <b>${state.deliveryValue}</b>。选择价值不超过此数的贸易站，并支付运费和圆片解锁费用。</p>${button('delivery','选择贸易站 →',false,'primary full')}<p class="bottom-note">外贸站须先建仓库。选站后查看运费、圆片要求和奖励，确认时自动结算。0 与 21 号本地站可重复运送。</p>`;
 if(state.phase==='forecastA'||state.phase==='forecastB'){const g=state.phase==='forecastA'?'A':'B';content=`<h2>威灵顿 · 预测 ${g}</h2><p>选择一片板块放入对应区域。未选板块保留，四步完成后自动补齐预测区。</p><div class="shelf tiles">${state.forecast[g].map(t=>tile(t,`data-forecast="${t.uid}"`,'放置此板块')).join('')}</div>${!state.forecast[g].length?button('emptyForecast','抽袋耗尽，继续'):''}`;}
 if(state.phase==='C')content=`<h2>${state.final?'最后一轮':'补牌，准备下回合'}</h2><p>${state.final?'本轮不执行补牌。剩余 '+state.final.remaining+' 名玩家（含当前玩家）完成后结束。':`将手牌补至 ${p.handLimit} 张。若牌库耗尽，自动洗混弃牌堆继续抽取。`}</p>${button('next','完成回合 →',false,'primary full')}`;
 return resources()+content+`<div class="notice">${state.mode==='sarah'?'你的回合结束后，系统翻开并结算莎拉行动卡。':state.players.length===1?'基础规则练习，没有电脑对手。':'同屏模式切换玩家时会遮住手牌。'}${state.rulesVersion?'费用与奖励自动结算。':'旧版对局包含手动裁定。'}规则可在右侧「规则」查看。</div>`;
}
function marketPanel(){return `<h2>公共市场</h2><div class="market-head"><b>绵羊市场</b>${state.rulesVersion?'':button('refillSheep','补充 2 张')}</div><span class="stack-count">市场牌库 ${state.sheepDeck.length}</span><div class="shelf" style="margin-top:10px">${state.sheepMarket.map(c=>card(c,`data-market-card="${c.uid}" data-group="sheep"`)).join('')}</div><h3>求职市场</h3><div class="shelf tiles">${state.workers.map(t=>tile(t,`data-market-tile="${t.uid}" data-group="worker"`,`${WORKER_NAMES[WORKERS.indexOf(catalog.tiles[t.def].name)]} · ${8-t.row} 元`)).join('')}</div><h3>目标展示区（从左到右）</h3><div class="shelf">${state.objectiveMarket.map(c=>card(c,`data-market-card="${c.uid}" data-group="objective"`)).join('')}</div><h3>奖励板块市场</h3><div class="shelf tiles">${state.bonuses.map(t=>tile(t,`data-market-tile="${t.uid}" data-group="bonus"`,`第 ${t.row+1} 行 · ${t.col+1} 列`)).join('')}</div><h3>天灾</h3><div class="shelf tiles">${state.hazards.map(t=>tile(t,`data-market-tile="${t.uid}" data-group="hazard"`,catalog.tiles[t.def].name==='flood'?'洪水':'落石')).join('')}</div><h3>港务长</h3><div class="shelf tiles">${state.harbourmasters.map(t=>tile(t,`data-market-tile="${t.uid}" data-group="master"`,'港务长')).join('')}</div><h3>牌组建构与奖励卡</h3>${Object.entries(state.supply).map(([g,cs])=>`<div class="market-head"><b>${escape(g.startsWith('bonus')?`奖励组 ${g.slice(5)}`:({romney:'罗姆尼羊',dog:'边境牧羊犬',ferry:'渡轮',bird:'翠鸟'})[g])}</b><span class="stack-count">剩余 ${cs.length}</span></div>${cs[0]?`<div class="shelf">${card(cs[0],`data-market-card="${cs[0].uid}" data-group="${g}"`)}</div>`:''}`).join('')}`;}
function estatePanel(){const p=current(state);return `<h2>${escape(p.name)}的牧场</h2>${resources()}${playerDashboard(p,state)}${state.rulesVersion?'':button('adjustWorker','派驻／调整工人')+button('flipNeutral',state.neutralFlipped?'中立建筑 II 面':'中立建筑 I 面')}<h3>可建造的私有建筑</h3><div class="shelf tiles">${p.private.map(t=>tile(t,`data-building="${t.uid}"`)).join('')}</div><h3>已接受的目标</h3><div class="shelf">${p.objectives.map(c=>card(c,`data-view-card="${c.def}"`)).join('')||'<p class="muted">尚未打出目标卡。</p>'}</div><h3>收集的板块</h3><div class="shelf tiles">${p.collected.map(t=>tile(t,`data-view-tile="${t.def}"`)).join('')}</div><div class="actions-row">${button('import','导入存档')}${button('export','导出存档')}${state.rulesVersion?'':button('end','触发最后一轮',!!state.final,'danger')}</div>`;}
function rulesPanel(){return `<h2>规则与记录</h2><div class="rules">${HELP.map(([title,text])=>`<details><summary>${title}</summary><p>${text}</p></details>`).join('')}</div><div class="rules-links"><a href="./MAPPING.md" target="_blank" rel="noopener">查看当前实现范围与来源 ↗</a></div><h3>行动日志</h3><ol class="log-list" reversed>${[...state.log].reverse().map(l=>`<li><small>回合 ${l.turn} · ${escape(state.players[l.player]?.name)}</small><br>${escape(l.text)}</li>`).join('')}</ol>`;}
function scoreScreen(){const totals=state.players.map(p=>score(state,p,catalog));root.innerHTML=top()+`<main class="score-wrap"><span class="eyebrow">THE SEASON'S HARVEST</span><h1>${state.phase==='ended'?'最终计分':'计分记录'}</h1><p>${state.rulesVersion?'全部项目按游戏状态自动计算；目标采用最佳合法物件分配，已打出而未完成的目标扣分。':'旧版辅助对局：部分项目需要填写。'}</p><table><thead><tr><th>计分项目</th>${state.players.map(p=>`<th>${escape(p.name)}</th>`).join('')}</tr></thead><tbody>${SCORE_LABELS.map((name,i)=>`<tr><td>${i+1}. ${name}<small>${SCORE_TIPS[i]}</small></td>${state.players.map((p,j)=>`<td>${(state.rulesVersion||[0,4].includes(i))?`<b>${totals[j].values[i]}</b>`:`<input type="number" aria-label="${escape(p.name+' '+name)}" min="-200" max="500" data-score-player="${j}" data-score-index="${i}" value="${p.scores[i]}">${i===6?`<small>含绵羊共 ${totals[j].values[i]} 分</small>`:''}`}</td>`).join('')}</tr>`).join('')}</tbody><tfoot><tr><td>总分</td>${state.players.map((p,j)=>`<td>${totals[j].total}</td>`).join('')}</tr></tfoot></table><div class="actions-row">${button(state.phase==='ended'?'reopen':'backGame',state.phase==='ended'?'返回桌面继续记录':'返回桌面')}${button('export','导出本局')}${button('new','新对局')}</div></main>`;}
function mobileDock(){
 if(mobileScreen==='map'){
  if(mapChoice)return `<div><strong>${escape(mapChoice.title)}</strong><small>${escape(mapChoice.hint||'点击高亮位置查看费用并确认')}</small></div><button data-map-cancel>取消</button>`;
  const r=previewRoute();if(r)return `<div><strong>${escape(LAND_NODES[r.destination].label)} · ${r.steps} 步 · ${r.fee} 元</strong><button data-mobile-routes>查看／切换路线</button></div><button data-move-cancel>取消</button><button data-move-confirm class="primary">确认移动</button>`;
  return `<div><strong>${canMapMove()?'点击高亮地点移动':'查看地图'}</strong><small>${canMapMove()?'选点后预览费用，确认后才移动':'通过行动页选择建造、航海或运送'}</small></div><button data-mobile-screen="turn">行动</button>`;
 }
 if(mobileScreen==='hand'){
  const p=current(state);if(p.isSarah)return '';
  if(state.pending)return `<div><strong>已选 ${selected.size} / ${state.pending.discard} 张</strong><small>抽换后选择要弃掉的牌</small></div>${button('discard','确认弃牌',selected.size!==state.pending.discard,'primary')}`;
  if(state.phase==='income')return `<div><strong>已选 ${selected.size} 张绵羊</strong><small>同品种只能选一张</small></div>${button('income','运羊收入',!selected.size,'primary')}`;
  if(state.phase==='start')return `<div><strong>首次准备 · 保留 4 张</strong><small>现在 ${p.hand.length} 张，已选 ${selected.size} 张</small></div>${p.hand.length===4?'<button data-auto="start" class="primary">选择圆片</button>':button('discard','确认弃牌',p.hand.length-selected.size!==4,'primary')}`;
 }
 return '';
}
function renderMobile(){
 const previousView=root.querySelector('#board-viewport');if(previousView)mobileMapView={x:previousView.scrollLeft,y:previousView.scrollTop,width:previousView.querySelector('#board').style.width,state:mobileState};
 const changed=mobileState!==state;if(changed){mobileState=state;mobileScreen=suggestedScreen(state);mobileMapView=null;}
 if(mapChoice||placing)mobileScreen='map';
 const oldPage=root.querySelector('#mobile-page'),pageScroll=oldPage?.scrollTop||0,oldScreen=oldPage?.dataset.screen;
 let content=mobileScreen==='map'?boardHtml():mobileScreen==='hand'?handHtml():mobileScreen==='market'?marketPanel():mobileScreen==='estate'?estatePanel():mobileScreen==='rules'?rulesPanel():turnPanel();
 if(mobileScreen==='turn'&&state.phase==='income')content=`<h2>选择要运送的羊</h2><p>到手牌页选择不同品种的绵羊，再确认收入。</p><button data-mobile-screen="hand" class="primary full">选择手牌</button>`;
 if(mobileScreen==='turn'&&state.pending)content=`<h2>完成抽换手牌</h2><p>还需要弃掉 ${state.pending.discard} 张牌。</p><button data-mobile-screen="hand" class="primary full">选择弃牌</button>`;
 root.innerHTML=mobileShell(state,mobileScreen,content,mobileDock(),!!history.length);
 const page=root.querySelector('#mobile-page');page.dataset.screen=mobileScreen;if(!changed&&oldScreen===mobileScreen)page.scrollTop=pageScroll;
 const view=root.querySelector('#board-viewport');if(view){
  if(mobileMapView&&!changed){view.querySelector('#board').style.width=mobileMapView.width;view.scrollLeft=mobileMapView.x;view.scrollTop=mobileMapView.y;}
  else frameMap(view,mapChoice?.targets.length?mapChoice.targets:canMapMove()?mapRoutes().map(r=>LAND_NODES[r.destination]):[rancherPosition(current(state))]);
 }
}
function mobileMenu(){showDialog(`<h2>对局与工具</h2><div class="mobile-menu">${button('scores','查看计分')}${button('export','导出存档')}${button('import','导入存档')}<button data-open-rules>规则与日志</button>${button('new','开始新对局')}<a href="../../">返回桌边首页</a></div>`,()=>{modal.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{modal.close();handleAction(el.dataset.action);});modal.querySelector('[data-open-rules]').onclick=()=>{modal.close();mobileScreen='rules';render();};});}
function mobileRoutes(){const r=previewRoute();if(!r)return;showDialog(`<h2>选择前往${escape(LAND_NODES[r.destination].label)}的路线</h2><div class="move-routes">${mapRoutes().filter(t=>t.destination===r.destination).map(t=>`<button data-route-option="${escape(t.path.join('|'))}" aria-pressed="${t.path.join('|')===movePreview}"><b>${t.steps} 步 · ${t.fee} 元</b><br>${escape(t.path.map(id=>LAND_NODES[id].label).join(' → '))}</button>`).join('')}</div>`,()=>modal.querySelectorAll('[data-route-option]').forEach(el=>el.onclick=()=>{movePreview=el.dataset.routeOption;modal.close();render();}));}
function render(){
 if(mapChoice?.state!==state)mapChoice=null;
 if(!state){showLanding();return;}
 const scroll=root.querySelector('#board-viewport'),pos=scroll?{x:scroll.scrollLeft,y:scroll.scrollTop}:null,sideScroll=root.querySelector('.side-body')?.scrollTop||0,handScroll=root.querySelector('.side>.hand-panel')?.scrollTop||0,handCardsScroll=root.querySelector('.side>.hand-panel .cards')?.scrollLeft||0;
 if(tab==='scores'||state.phase==='ended'){scoreScreen();return;}
 if(curtain){root.innerHTML=top()+`<main class="curtain"><span class="eyebrow">NEXT RUNHOLDER</span><h1>请交给<br>${escape(current(state).name)}</h1><p>准备好后再查看自己的手牌。</p>${button('reveal','轮到我了',false,'primary')}</main>`;return;}
 if(isMobile()){renderMobile();return;}
 root.innerHTML=top()+`<div class="statusbar"><span class="round">第 ${state.turn} 回合</span><strong><span class="status-player" style="background:${COLORS[state.active]}"></span>${escape(current(state).name)}</strong><span class="phase-pill">${PHASES[state.phase]}</span><span class="right">${saveError?escape(saveError):'进度已保存在此浏览器'} · ${state.final?'最后一轮':state.mode==='sarah'?(state.rulesVersion?'官方莎拉 · 自动结算':'旧版莎拉 · 规则辅助'):state.players.length===1?'单人基础练习':state.players.length+' 人同屏'}</span></div>${!state.rulesVersion?'<div class="notice">这是旧版辅助存档。请先导出保留，再通过「新对局」体验自动规则。</div>':''}<main class="layout"><div class="board-panel">${boardHtml()}</div><aside class="side"><nav class="tabs" aria-label="桌面面板">${[['turn','回合'],['market','市场'],['estate','牧场'],['rules','规则']].map(([id,label])=>`<button data-tab="${id}" class="${tab===id?'active':''}" aria-pressed="${tab===id}">${label}</button>`).join('')}</nav><div class="side-body">${tab==='turn'?turnPanel():tab==='market'?marketPanel():tab==='estate'?estatePanel():rulesPanel()}</div>${handHtml()}</aside></main>`;
 if(!pos)root.querySelector('#board-viewport').scrollTop=root.querySelector('#board-viewport').scrollHeight;
 if(pos){root.querySelector('#board-viewport').scrollLeft=pos.x;root.querySelector('#board-viewport').scrollTop=pos.y;}root.querySelector('.side-body').scrollTop=sideScroll;root.querySelector('.side>.hand-panel').scrollTop=handScroll;const cards=root.querySelector('.side>.hand-panel .cards');if(cards)cards.scrollLeft=handCardsScroll;
}
function adjust(field){const p=current(state);formDialog(`记录${RESOURCE_LABELS[field]}`,'<p>按刚才执行的原图效果填写变化后的数值。此操作会保留在行动日志中。</p>',number('value','调整后数值',p[field],field==='handLimit'||field==='steps'?1:0)+`<div class="form-row"><label>原因<input name="note" placeholder="例如：解锁圆片奖励" maxlength="150"></label></div>`,d=>dispatch({type:'adjust',field,label:RESOURCE_LABELS[field],value:Number(d.get('value')),note:d.get('note')}));}
function beginPlacement(spec){placing=spec;modal.close();tab='turn';render();toast(spec.text+'，然后点击地图');}
function movementDialog(x,y,location,wellington=false,destination=null){
 const p=current(state),isSarah=!!p.isSarah,sites=tollSites(state,catalog).filter(t=>t.owner!==state.active&&(!isSarah||t.owner>=0));
 const end=sites.find(t=>t.uid===destination),via=[];
 let exempt=!!p.tollExempt;
 const route=()=>[...via,...(end?[end.uid]:[])];
 showDialog(`<h2>${isSarah?'莎拉移动':'移动到'+escape(location)}</h2><p>${isSarah?`正常移动 ${state.sarah.move.normal} 步，额外移动 ${state.sarah.move.extra||0} 步。`:`移动上限 ${p.steps} 步。`}按经过顺序添加途中的收费地点。终点的收费板块自动计入；空格、中立建筑和自己的建筑不收费。</p><p class="muted">仍需核对道路箭头、分岔路线及步数；这里只选择实际经过的收费地点。</p>
 <div class="form-row"><label>途中经过<select id="toll-site"><option value="">选择收费地点</option>${sites.filter(t=>t.uid!==destination).map(t=>`<option value="${t.uid}">${escape(t.label)} · ${t.fee} 元（${t.x.toFixed(1)}, ${t.y.toFixed(1)}）</option>`).join('')}</select></label><button id="add-toll">添加经过地点</button></div>
 ${!isSarah&&(p.pioneer>=11||p.tollExempt)?`<label><input id="toll-exempt" type="checkbox" ${exempt?'checked':''}>已在开拓者 11 格选择免过路费（费用板块 X 面）</label>`:''}
 <div id="toll-summary" aria-live="polite"></div><p class="error" id="toll-error"></p><div class="dialog-actions"><button id="confirm-move" class="primary">确认移动</button><button id="cancel-move">取消</button></div>`,()=>{
  const update=()=>{
   const items=quoteTolls(state,catalog,route(),{exempt});
   modal.querySelector('#toll-summary').innerHTML=items.length?`<ol>${items.map(t=>`<li>${escape(t.label)}${end?.uid===t.uid?'（终点）':''} → ${t.owner<0?'供应区':escape(state.players[t.owner].name)}：${t.paid} 元${t.paid<t.due?'（余额不足，剩余免付）':''}${end?.uid===t.uid?'':` <button data-remove-toll="${t.uid}">移除</button>`}</li>`).join('')}</ol><p><b>${isSarah?'供应区代付':'本次支付'} ${items.reduce((n,t)=>n+t.paid,0)} 元</b>${exempt&&!isSarah?' · 已免过路费':''}</p>`:'<p>当前所选路线无过路费。</p>';
   modal.querySelectorAll('[data-remove-toll]').forEach(b=>b.onclick=()=>{via.splice(via.indexOf(b.dataset.removeToll),1);update();});
   modal.querySelectorAll('#toll-site option').forEach(o=>{o.disabled=via.includes(o.value);});
  };
  modal.querySelector('#add-toll').onclick=()=>{const uid=modal.querySelector('#toll-site').value;if(uid&&!via.includes(uid)){via.push(uid);modal.querySelector('#toll-site').value='';update();}};
  const checkbox=modal.querySelector('#toll-exempt');if(checkbox)checkbox.onchange=()=>{exempt=checkbox.checked;update();};
  modal.querySelector('#cancel-move').onclick=()=>modal.close();
  modal.querySelector('#confirm-move').onclick=()=>{const action={type:isSarah?'sarahMove':'move',x,y,location,wellington,route:route()};if(checkbox)action.tollExempt=exempt;if(dispatch(action))modal.close();};
  update();
 });
}
function sarahMoveTo(x,y,wellington,destination=null){movementDialog(x,y,'自选地点',wellington,destination);}
function moveTo(x,y,location,wellington=false,destination=null){if(state.rulesVersion){chooseDestination(wellington?'W':nearestLand(x,y).id);return;}movementDialog(x,y,location,wellington,destination);}
function inspectNeutral(id){const n=NEUTRAL.find(n=>n.id===id),d=catalog.tiles[id],face=state.neutralFlipped&&['B','C','G','H'].includes(n.letter)?d.back:d.image;showDialog(`<h2>中立建筑 ${n.letter}</h2><img class="detail-image" src="${face}" alt="建筑 ${n.letter}"><ol>${n.actions.map(a=>`<li>${a}</li>`).join('')}</ol><p class="muted">印刷卡面为最终依据。翻面后的行动请查附录。</p><div class="dialog-actions">${button('goNeutral','移动至此',state.phase!=='A','primary')}${button('flipView','查看背面')}</div>`,()=>{modal.querySelector('[data-action=goNeutral]').onclick=()=>moveTo(n.x,n.y,`中立建筑 ${n.letter}`);modal.querySelector('[data-action=flipView]').onclick=()=>{const im=modal.querySelector('.detail-image');im.src=im.src.endsWith(d.image)?d.back:d.image;};});}
function inspectCard(c,group){const d=info(c);if(state.rulesVersion&&group){if(group.startsWith('bonus'))formDialog('用金块购买奖励卡',`<img class="detail-image" src="${d.image}" alt="${escape(d.name)}"><p>系统按本局奖励组位置扣除 3／3／4／5 金块。</p>`,'',()=>dispatch({type:'gainCard',group,uid:c.uid,gold:true}));else showDialog(`<h2>${escape(d.name)}</h2><img class="detail-image" src="${d.image}" alt="${escape(d.name)}"><p>从回合面板选择相应地点行动来获得此卡。</p>`);return;}if(group){formDialog(`获得${d.name}`,`<img class="detail-image" src="${d.image}" alt="${escape(d.name)}"><p>按地点行动和已分配的牧羊人确定费用；卡牌加入弃牌区。特殊奖励、紫羊交换指示物另行结算。</p>`,number('cost','本次支付钱币',0)+(group.startsWith('bonus')?'<label><input name="gold" type="checkbox">使用金块购买（按本组价格扣除）</label>':''),data=>dispatch({type:'gainCard',group,uid:c.uid,cost:Number(data.get('cost')),gold:data.has('gold')}),'获得此卡');return;}
 showDialog(`<h2>${escape(d.name)}</h2><img class="detail-image" src="${d.image}" alt="${escape(d.name)}">${d.kind==='sheep'?`<p>育种价值 ${d.value} · 羊毛 ${d.wool} · 分数 ${d.vp}</p>`:'<p>行动前或行动之间可以打出。除翠鸟的前进与普通功能卡补抽外，其他卡面效果请使用桌面工具结算。</p>'}<div class="dialog-actions">${button('playInspected','打出此卡',d.kind==='sheep','primary')}${state.rulesVersion?'':button('removeInspected','按效果永久移除')}${d.color==='gray'?button('removeWithExchange','消耗 2 交换移除并得金块'):''}</div>`,()=>{modal.querySelector('[data-action=playInspected]').onclick=()=>{if(dispatch({type:'playCard',uid:c.uid}))modal.close();};if(modal.querySelector('[data-action=removeInspected]'))modal.querySelector('[data-action=removeInspected]').onclick=()=>{if(dispatch({type:'removeCard',uid:c.uid}))modal.close();};modal.querySelector('[data-action=removeWithExchange]')?.addEventListener('click',()=>{if(dispatch({type:'removeCard',uid:c.uid,exchange:true}))modal.close();});});}
function inspectTile(t,group){const d=catalog.tiles[t.def];if(state.rulesVersion){showDialog(`<h2>${escape(d.name)}</h2><img class="detail-image" src="${d.image}" alt="${escape(d.name)}"><p>在回合面板通过对应行动获得此板块，费用和奖励自动结算。</p>`);return;}formDialog(group==='worker'?'雇用工人':group==='hazard'?'移除天灾':group==='master'?'取得港务长':'投资奖励板块',`<img class="detail-image" src="${d.image}" alt="${escape(d.name)}"><p>${group==='worker'?'系统增加对应工人数；按玩家图板另行结算新覆盖的即时奖励。':group==='hazard'?'天灾移入你的收集区，并自动加入对应的牧羊犬或渡轮。':'请先确认满足全部费用与条件，取得后按卡面结算奖励。'}</p>`,number('cost','实际支付钱币',group==='worker'?8-t.row:group==='hazard'?5:0),data=>dispatch({type:group==='worker'?'hire':'takeTile',group,uid:t.uid,cost:Number(data.get('cost'))}));}
function listCards(title,cards){showDialog(`<h2>${escape(title)}</h2><div class="cards">${cards.map(c=>card(c,`data-view-card="${c.def}"`)).join('')||'<p>此区域为空。</p>'}</div>`);}
function deliveryDialog(){
 const xs=[59.3,52.8,46.3,39.6,33,26.7,20.2,13.8,7.2],req=[0,1,3,6,9,12,15,18,21],fees=[0,0,0,0,3,4,5,6,7];
 formDialog('选择本次贸易站',`<p>本次价值 ${state.deliveryValue}。外贸站需要先有自己的仓库。圆片解锁奖励与贸易站卡牌按原图结算。</p>`,`<div class="form-row"><label>贸易站<select name="station">${req.map((v,i)=>`<option value="${i}" ${v>state.deliveryValue?'disabled':''}>当地贸易站 ${v}</option>`).join('')}<option value="foreign">已解锁的外贸站（地图定位）</option></select></label></div>`+number('extra','圆片额外解锁费用',0),d=>{const extra=Number(d.get('extra'));if(d.get('station')==='foreign'){beginPlacement({kind:'foreignDelivery',extra,text:'选择已建仓库的外贸站'});return true;}const i=Number(d.get('station'));return dispatch({type:'delivery',value:req[i],station:`当地 ${req[i]}`,x:xs[i],y:36.6,cost:fees[i]+extra});});
}

function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>5_000_000)throw new Error('存档文件过大');const data=JSON.parse(await file.text()),next=validateSave(data.state||data,catalog);if(state&&!window.confirm('导入存档会替换当前对局，是否继续？'))return;state=next;history=[];selected.clear();placing=null;curtain=false;tab='turn';save();render();toast('存档已导入');}catch(e){toast('无法导入：'+e.message);}};input.click();}
function exportSave(){const blob=new Blob([JSON.stringify({format:'new-zealand-table',version:VERSION,state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`新西兰-第${state.turn}回合.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function handleAction(id){
 const p=state?current(state):null;
 if(isMobile()&&['zoomin','zoomout','fit','land','sea'].includes(id)){
  const view=root.querySelector('#board-viewport'),board=view?.querySelector('#board');if(!board)return;
  if(id==='land'||id==='sea'||id==='fit'){frameMap(view,id==='sea'?[{x:5,y:2},{x:95,y:30}]:id==='land'?[{x:5,y:44},{x:74,y:94}]:mapChoice?.targets.length?mapChoice.targets:canMapMove()?mapRoutes().map(r=>LAND_NODES[r.destination]):[rancherPosition(p)]);}
  else{const old=board.clientWidth,cx=(view.scrollLeft+view.clientWidth/2)/old,cy=(view.scrollTop+view.clientHeight/2)/(old*1.5);board.style.width=Math.max(500,Math.min(1600,old*(id==='zoomin'?1.25:.8)))+'px';view.scrollLeft=cx*board.clientWidth-view.clientWidth/2;view.scrollTop=cy*board.clientHeight-view.clientHeight/2;}
  return;
 }
 switch(id){
 case 'import':importSave();break;case 'export':exportSave();break;
 case 'undo':if(history.length){state=history.pop();selected.clear();placing=null;curtain=false;save();render();toast('已撤销上一步');}break;
 case 'new':if(!state||window.confirm('开始新对局？当前进度将被替换，建议先导出存档。')){state=null;history=[];selected.clear();tab='turn';placing=null;curtain=false;render();}break;
 case 'scores':tab='scores';render();break;case 'backGame':tab='turn';render();break;
 case 'reopen':tab='turn';dispatch({type:'reopen'});break;
 case 'reveal':curtain=false;render();break;
 case 'sarahMove':beginPlacement({kind:'sarahMove',text:'选择莎拉本回合的目的地'});break;
 case 'sarahWellington':sarahMoveTo(86,46,true);break;
 case 'sarahEnd':dispatch({type:'sarahEnd'});break;
 case 'sarahSkipBuild':if(window.confirm('确认所有可建造选项均无合法位置？'))dispatch({type:'sarahSkipBuild'});break;
 case 'sarahPort':beginPlacement({kind:'sarahPort',text:'选择按规则优先级确定的中型港口'});break;
 case 'start':dispatch({type:'start'});break;
 case 'zoomin':zoom=Math.min(250,zoom+25);render();break;case 'zoomout':zoom=Math.max(70,zoom-25);render();break;case 'fit':zoom=100;render();break;
 case 'land':root.querySelector('#board-viewport').scrollTop=root.querySelector('#board-viewport').scrollHeight;break;case 'sea':root.querySelector('#board-viewport').scrollTop=0;break;
 case 'mapHelp':showDialog('<h2>路线图操作</h2><p>地图上部为海路、下部为南岛，右侧为公共市场。陆路沿箭头前进；海路虚线可双向通行。</p><p>移动时点击高亮目的地查看路线。建造、航海和运送通过回合面板进入地图选择，再点击高亮位置确认。点选卡牌或建筑可放大查看数值与行动。</p><p>地图支持缩放和滚动，南岛／海路按钮可快速定位。</p>');break;
 case 'cancelPlacement':placing=null;render();break;
 case 'manualMove':beginPlacement({kind:'move',text:'选择牧场主的目的地'});break;
 case 'wellington':if(state.phase!=='A'){toast('请先进入移动阶段');break;}moveTo(86,46,'威灵顿',true);break;
 case 'discard':dispatch({type:'discard',uids:[...selected]});break;
 case 'showDiscard':listCards('弃牌堆（公开信息）',p.discard);break;
 case 'cardDetail':{const c=p.hand.find(c=>selected.has(c.uid));if(c){if(state.rulesVersion&&info(c).kind!=='sheep')autoDialog(state,catalog,'card:'+c.uid,{formDialog,dispatch,selected});else inspectCard(c);}break;}
 case 'exchange':formDialog('交换手牌','<p>消耗一个交换指示物，先抽牌，再选择等量手牌弃掉。</p>',number('count','抽换数量',2,1,2),d=>dispatch({type:'exchange',count:Number(d.get('count'))}));break;
 case 'draw':formDialog('按效果抽牌','<p>请确认原图效果允许抽牌。抽换模式会要求完成等量弃牌。</p>',number('count','抽牌数量',1,1,10)+`<label><input type="checkbox" name="cycle" checked>需要等量弃牌（抽换）</label>`,d=>dispatch({type:'draw',count:Number(d.get('count')),cycle:d.has('cycle')}));break;
 case 'finishB':dispatch({type:'next'});break;
 case 'next':{const old=state.active;if(dispatch({type:'next'})&&state.active!==old&&state.phase!=='ended'&&state.mode!=='sarah'){curtain=true;render();}break;}
 case 'income':{
  let value;try{value=sheepValue(state,catalog,[...selected]);}catch(e){toast(e.message);break;}
  const uids=[...selected];formDialog('领取运羊收入',`<p>所选绵羊价值 ${value}，永久认证 ${p.permanentCertificate}。只有所选绵羊会被弃掉。</p>`,number('certificate','使用临时认证',0,0,p.certificate),d=>dispatch({type:'income',uids,certificate:Number(d.get('certificate'))}));break;}
 case 'delivery':deliveryDialog();break;
 case 'emptyForecast':dispatch({type:'emptyForecast'});break;
 case 'shear':{const uids=[...selected];let value;try{value=sheepValue(state,catalog,uids,'wool')+p.wool;}catch(e){toast(e.message);break;}formDialog('给所选绵羊剃毛',`<p>所选绵羊 ${uids.length} 张，本次收入 ${value} 元（含永久羊毛）。请核对该地点允许分配的剃毛工人数。</p>`,number('limit','本次允许的羊数量',p.workers[3],1,5),d=>dispatch({type:'shear',uids,limit:Number(d.get('limit'))}));break;}
 case 'marketTab':tab='market';render();break;
 case 'refillSheep':dispatch({type:'refillSheep',count:2});break;
 case 'placeShip':case 'placeDisk':case 'placeWarehouse':beginPlacement({kind:id==='placeShip'?'ship':id==='placeDisk'?'disk':'warehouse',text:id==='placeShip'?'选择帆船停靠的海路格':id==='placeDisk'?'选择圆片放置位置':'选择仓库放置港口'});break;
 case 'adjustWorker':formDialog('派驻／调整工人','<p>派驻港务长后减少一名工人；获得万能工人时选择对应行增加。基础内建工人不能派出。</p>',`<div class="form-row"><label>工人类型<select name="worker">${WORKER_NAMES.map((n,i)=>`<option value="${i}">${n}（当前 ${p.workers[i]}）</option>`).join('')}</select></label></div>`+number('value','调整后数量',1,1,5),d=>dispatch({type:'adjustWorker',worker:Number(d.get('worker')),value:Number(d.get('value'))}));break;
 case 'flipNeutral':dispatch({type:'flipNeutral'});break;
 case 'rewardAction':tab='turn';mobileScreen='turn';render();break;
 case 'aux':formDialog('附属行动','<p>请核对该附属行动已解锁，以及本次允许执行的次数。执行后也请在地点行动列表记完成。</p>',`<div class="form-row"><select name="kind"><option value="money">获得钱币</option><option value="certificate">付 2 元，认证 +1</option><option value="pioneer">付 1 元，开拓者 +1</option></select></div>`+number('count','执行次数',1,1,2),d=>{const kind=d.get('kind'),n=Number(d.get('count'));if(kind==='money')return dispatch({type:'adjust',field:'money',value:p.money+n,note:'附属行动'});const cost=(kind==='certificate'?2:1)*n;if(p.money<cost)throw new Error('钱币不足');return batch([{type:'adjust',field:'money',value:p.money-cost,note:'附属行动费用'},{type:'adjust',field:kind,value:Math.min(kind==='certificate'?p.certificateMax:16,p[kind]+n),note:'附属行动'}]);});break;
 case 'end':if(window.confirm('确认奖励市场已触发结束？当前及其他玩家完成最后回合后计分。'))dispatch({type:'end'});break;
 }
}
root.addEventListener('click',e=>{
 const el=e.target.closest('button,a');if(!el)return;
 if(el.dataset.pbDetail){showDialog(`<h2>工人格奖励</h2><p>${escape(el.dataset.pbDetail)}</p><p>到达该格时自动结算。需要选牌、建造或移动的奖励，会进入当前行动。</p>`);return;}
 if(el.dataset.mobileScreen){mobileScreen=el.dataset.mobileScreen;render();return;}
 if(el.hasAttribute('data-mobile-menu')){mobileMenu();return;}
 if(el.hasAttribute('data-mobile-routes')){mobileRoutes();return;}
 if(el.hasAttribute('data-map-choice')){mapChoice?.choose(mapChoice.targets[Number(el.dataset.mapChoice)]);return;}
 if(el.hasAttribute('data-map-cancel')){mapChoice=null;if(isMobile())mobileScreen='turn';render();return;}
 if(el.dataset.moveDestination){chooseDestination(el.dataset.moveDestination);return;}
 if(el.dataset.movePath){movePreview=el.dataset.movePath;previewState=state;render();return;}
 if(el.hasAttribute('data-move-confirm')){const r=previewRoute();if(r)dispatch({type:'autoMove',path:r.path.join('|')});return;}
 if(el.hasAttribute('data-move-cancel')){movePreview=null;render();return;}

 if(el.dataset.action){void handleAction(el.dataset.action);return;}
 if(el.dataset.sarahRoute){dispatch({type:'sarahAutoMove',path:el.dataset.sarahRoute});return;}
 if(el.dataset.sarahPort){dispatch({type:'sarahAutoPort',port:el.dataset.sarahPort});return;}
 if(el.dataset.sarahChoice){const option=state.sarah.choices.find(c=>c.key===el.dataset.sarahChoice);if(state.sarah.stage==='build'&&!option.oldUid&&!state.rulesVersion)beginPlacement({kind:'sarahBuild',key:option.key,text:'选择莎拉建筑的合法空位'});else dispatch({type:'sarahChoice',key:option.key});return;}
 if(el.dataset.tab){tab=el.dataset.tab;render();root.querySelector('.side-body').scrollTop=0;return;}
 if(el.dataset.hand){selected.has(el.dataset.hand)?selected.delete(el.dataset.hand):selected.add(el.dataset.hand);render();return;}
 if(el.dataset.resource&&state.rulesVersion){toast('资源由规则自动结算');return;}
 if(el.dataset.resource){adjust(el.dataset.resource);return;}
 if(el.dataset.mark){const n=NEUTRAL.find(n=>`中立建筑 ${n.letter}`===current(state).location);dispatch({type:'markAction',key:el.dataset.mark,label:state.neutralFlipped?'按 II 面执行行动':n.actions[Number(el.dataset.mark)]});return;}
 if(el.dataset.forecast){dispatch({type:'forecast',uid:el.dataset.forecast});return;}
 if(el.dataset.marketCard){const g=el.dataset.group,zone=g==='sheep'?state.sheepMarket:g==='objective'?state.objectiveMarket:state.supply[g];inspectCard(zone.find(c=>c.uid===el.dataset.marketCard),g);return;}
 if(el.dataset.marketTile){const g=el.dataset.group,zone={worker:state.workers,bonus:state.bonuses,hazard:state.hazards,master:state.harbourmasters}[g];inspectTile(zone.find(t=>t.uid===el.dataset.marketTile),g);return;}
 if(el.dataset.building&&state.rulesVersion){const t=current(state).private.find(t=>t.uid===el.dataset.building);showDialog(`<h2>私有建筑</h2><img class="detail-image" src="${t.side==='b'?catalog.tiles[t.def].back:catalog.tiles[t.def].image}" alt="建筑"><p>在回合面板通过建造行动选择建筑和合法空位。</p>`);return;}
 if(el.dataset.building){const t=current(state).private.find(t=>t.uid===el.dataset.building),d=catalog.tiles[t.def];showDialog(`<h2>${escape(d.name)}</h2><img class="detail-image" src="${d.image}" alt="${escape(d.name)}"><p>请先核对工匠数量、建造费用与空位要求。默认全部建筑使用 a 面。</p><div class="dialog-actions">${button('buildHere','选择建造位置',state.phase!=='B','primary')}${button('replaceHere','替换已有建筑',state.phase!=='B')}</div>`,()=>{modal.querySelector('[data-action=buildHere]').onclick=()=>beginPlacement({kind:'building',uid:t.uid,text:'选择私有建筑的空位'});modal.querySelector('[data-action=replaceHere]').onclick=()=>{const old=state.boardPieces.filter(b=>b.type==='building'&&b.owner===state.active);formDialog('替换私有建筑','<p>按新旧建筑工匠需求差支付费用。新建筑需求必须更高；旧建筑移出游戏，不获得金块。</p>',`<div class="form-row"><label>旧建筑<select name="old">${old.map(b=>`<option value="${b.uid}">${escape(catalog.tiles[b.def].name)}</option>`).join('')}</select></label></div>`+number('cost','替换费用',0),data=>dispatch({type:'replaceBuilding',uid:t.uid,oldUid:data.get('old'),cost:Number(data.get('cost'))}));};});return;}
 if(el.dataset.viewCard){const d=cardInfo(catalog.cards[el.dataset.viewCard]);showDialog(`<h2>${escape(d.name)}</h2><img class="detail-image" src="${d.image}" alt="${escape(d.name)}">`);return;}
 if(el.dataset.viewTile){const d=catalog.tiles[el.dataset.viewTile];showDialog(`<h2>板块详情</h2><img class="detail-image" src="${d.image}" alt="${escape(d.name)}">`);return;}
 // During placement a tile click denotes its map position, rather than opening its inspector.
 if(placing&&el.closest('#board'))return;
 if(el.dataset.neutral){inspectNeutral(el.dataset.neutral);return;}
 if(el.dataset.piece&&el.dataset.market){const g=el.dataset.market,zone={worker:state.workers,bonus:state.bonuses,hazard:state.hazards}[g];inspectTile(zone.find(t=>t.uid===el.dataset.piece),g);return;}
 if(el.dataset.ship!==undefined&&state.rulesVersion){if(state.ruleTasks?.[0]?.kind==='ship')autoDialog(state,catalog,'task',{formDialog,dispatch,selected});else toast('请先选择允许移动帆船的行动');return;}
 if(el.dataset.ship!==undefined){if(Number(el.dataset.ship)===state.active)beginPlacement({kind:'ship',text:'选择帆船停靠位置'});return;}
 if(el.dataset.rancher!==undefined&&canMapMove()){focusMap();return;}
 if(el.dataset.rancher!==undefined){if(Number(el.dataset.rancher)===state.active&&state.phase==='A')beginPlacement({kind:'move',text:'选择牧场主的目的地'});return;}
 if(el.dataset.token&&state.rulesVersion){toast('港口及圆片由升级和运送行动管理');return;}
 if(el.dataset.token){const t=state.boardPieces.find(t=>t.uid===el.dataset.token);showDialog(`<h2>${escape(state.players[t.owner].name)}的地图标记</h2><p>${escape(t.label||t.type)}</p><div class="dialog-actions">${button('relocateToken','重新定位')}${button('returnToken','按规则收回')}</div>`,()=>{modal.querySelector('[data-action=relocateToken]').onclick=()=>beginPlacement({kind:'relocate',uid:t.uid,text:'选择标记的新位置'});modal.querySelector('[data-action=returnToken]').onclick=()=>{if(dispatch({type:'returnToken',uid:t.uid}))modal.close();};});}
});
root.addEventListener('click',e=>{
 const board=e.target.closest('#board');if(!board)return;if(!placing&&e.target.closest('button'))return;
 const r=board.getBoundingClientRect(),piece=e.target.closest('[data-piece]'),destination=piece?.dataset.piece;let x=Math.round((e.clientX-r.left)/r.width*10000)/100,y=Math.round((e.clientY-r.top)/r.height*10000)/100;if(piece){x=parseFloat(piece.style.left);y=parseFloat(piece.style.top);}
 if(!placing){if(state.phase==='A')moveTo(x,y,'自选地点');return;}
 const spec=placing;placing=null;
 if(spec.kind==='sarahMove'){sarahMoveTo(x,y,false,destination);render();return;}
 if(spec.kind==='sarahBuild'){dispatch({type:'sarahChoice',key:spec.key,x,y});return;}
 if(spec.kind==='sarahPort'){formDialog('莎拉升级中型港口','<p>确认选择的是最低分的合法港口。莎拉不支付费用，也不保留港务长。没有港务长时选择「无」。</p>',number('points','该港口印刷分数',0,0,20)+`<div class="form-row"><label>移除的港务长<select name="master"><option value="">无</option>${state.harbourmasters.map((t,i)=>`<option value="${t.uid}">港务长 ${i+1}</option>`).join('')}</select></label></div><div class="form-row"><label>印刷奖励卡<select name="group"><option value="">无奖励／已耗尽</option>${Object.keys(state.supply).map(g=>`<option value="${g}">${escape(g)}</option>`).join('')}</select></label></div>`,d=>dispatch({type:'sarahPort',x,y,points:Number(d.get('points')),master:d.get('master'),group:d.get('group')}));render();return;}
 if(spec.kind==='relocate'){dispatch({type:'relocate',uid:spec.uid,x,y});return;}
 if(spec.kind==='foreignDelivery'){formDialog('运往已解锁外贸站','<p>填写原图标注的门槛和运费。必须已有仓库且符合圆片颜色要求。</p>',number('value','该站要求育种价值',Math.min(5,state.deliveryValue),0,state.deliveryValue)+number('fee','运费',0),d=>dispatch({type:'delivery',value:Number(d.get('value')),station:`外贸 ${x.toFixed(1)},${y.toFixed(1)}`,x,y,cost:spec.extra+Number(d.get('fee'))}));render();return;}
 if(spec.kind==='move'){moveTo(x,y,'自选地点',false,destination);render();return;}
 formDialog(spec.kind==='building'?'建造建筑':'记录放置',`<p>位置：地图 ${x.toFixed(1)}%, ${y.toFixed(1)}%。请确认满足路径、工人数量及放置要求，结算后记得处理卡牌和解锁效果。</p>`,number('cost','本次费用',0)+`<div class="form-row"><label>位置备注<input name="label" maxlength="60" placeholder="例如：羊毛贸易站 9"></label></div>`,d=>dispatch(spec.kind==='building'?{type:'build',uid:spec.uid,x,y,cost:Number(d.get('cost'))}:{type:'place',kind:spec.kind,x,y,cost:Number(d.get('cost')),label:d.get('label')}));render();
});
root.addEventListener('change',e=>{if(e.target.dataset.scorePlayer!==undefined){dispatch({type:'score',player:Number(e.target.dataset.scorePlayer),index:Number(e.target.dataset.scoreIndex),value:Number(e.target.value)});}});
modal.addEventListener('click',e=>{const el=e.target.closest('[data-view-card]');if(el){const d=cardInfo(catalog.cards[el.dataset.viewCard]);showDialog(`<h2>${escape(d.name)}</h2><img class="detail-image" src="${d.image}" alt="${escape(d.name)}">`);}});
mobileQuery.addEventListener('change',()=>{mobileMapView=null;render();});
try{const response=await fetch('./catalog.json');if(!response.ok)throw new Error(`素材加载失败（${response.status}）`);catalog=originalCatalog(await response.json());try{const raw=localStorage.getItem(KEY);if(raw){const data=JSON.parse(raw);state=validateSave(data.state,catalog);history=Array.isArray(data.history)?data.history.slice(-15).map(s=>validateSave(s,catalog)):[];}}catch(e){saveError='旧存档暂时无法读取，未删除原记录：'+e.message;}render();}catch(e){root.innerHTML=`<main class="landing"><h1>地图暂时未能展开</h1><p>${escape(e.message)}</p><button id="retry">重新加载</button><p>请通过项目的本地 HTTP 预览地址访问。</p></main>`;root.querySelector('#retry').onclick=()=>location.reload();}

root.addEventListener('click',e=>{const el=e.target.closest('[data-auto],[data-rule-id]');if(el?.dataset.auto==='move'){focusMap();return;}if(el)autoDialog(state,catalog,el.dataset.auto??el.dataset.ruleId,{formDialog,dispatch,selected});});
